<template>
  <main class="taxonomy-page"><div class="taxonomy-shell">
    <header><div><p>3B / ADMIN</p><h1>Category tree & merchandising</h1><span>Build a clean path through categories and control what customers see in navigation.</span></div><button class="button secondary" :disabled="loading" @click="load">Refresh</button></header>
    <p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p>
    <section class="panel"><div class="section-title"><div><p>TAXONOMY</p><h2>{{ categoryForm.id ? 'Edit category' : 'Add a main category' }}</h2></div><span>{{ categories.length }} main categories</span></div>
      <form class="form-grid" @submit.prevent="saveCategory">
        <label>English name<input v-model="categoryForm.name_en" required></label><label>Arabic name<input v-model="categoryForm.name_ar" dir="rtl" required></label><label>Slug<input v-model="categoryForm.slug" pattern="[A-Za-z0-9_-]+" placeholder="auto from English name"></label>
        <label>Icon key<input v-model="categoryForm.icon_key" placeholder="laptop, fridge, tv"></label><label>Order<input v-model.number="categoryForm.order" type="number" min="0"></label>
        <label class="check"><input v-model="categoryForm.is_active" type="checkbox"> Active</label><label class="check"><input v-model="categoryForm.show_in_menu" type="checkbox"> Show in navigation</label>
        <label>Desktop banner<input type="file" accept="image/jpeg,image/png,image/webp" @change="pick($event, 'desktop_banner')"></label><label>Mobile banner<input type="file" accept="image/jpeg,image/png,image/webp" @change="pick($event, 'mobile_banner')"></label>
        <label>English image alt text<input v-model="categoryForm.banner_alt_en"></label><label>Arabic image alt text<input v-model="categoryForm.banner_alt_ar" dir="rtl"></label>
        <label class="wide">English category description<textarea v-model="categoryForm.description_en" rows="3"></textarea></label><label class="wide">Arabic category description<textarea v-model="categoryForm.description_ar" rows="3" dir="rtl"></textarea></label>
        <label>English SEO title<input v-model="categoryForm.meta_title_en"></label><label>Arabic SEO title<input v-model="categoryForm.meta_title_ar" dir="rtl"></label><label>English SEO description<textarea v-model="categoryForm.meta_description_en" rows="2"></textarea></label><label>Arabic SEO description<textarea v-model="categoryForm.meta_description_ar" rows="2" dir="rtl"></textarea></label>
        <div class="actions"><button class="button primary" :disabled="saving">{{ categoryForm.id ? 'Save category' : 'Create category' }}</button><button v-if="categoryForm.id" class="button secondary" type="button" @click="resetCategory">Cancel</button></div>
      </form>
    </section>
    <section class="panel"><div class="section-title"><div><p>MAIN CATEGORY ORDER</p><h2>Visual category tree</h2></div></div>
      <article v-for="(category, index) in categories" :key="category.id" class="tree-category"><div class="tree-heading"><div><strong>{{ category.name_en }}</strong><small>{{ category.name_ar }} · /category/{{ category.slug }} · {{ category.is_active ? 'Active' : 'Hidden' }}</small></div><div class="row-actions"><button class="button secondary" :disabled="index === 0 || saving" aria-label="Move category up" @click="moveCategory(index, -1)">↑</button><button class="button secondary" :disabled="index === categories.length - 1 || saving" aria-label="Move category down" @click="moveCategory(index, 1)">↓</button><button class="button secondary" @click="editCategory(category)">Edit</button><button class="button secondary" @click="startSubcategory(category.id)">Add subcategory</button></div></div>
        <div v-for="sub in childrenOf(category.id)" :key="sub.id" class="tree-subcategory"><div class="tree-heading"><div><strong>{{ sub.name_en }}</strong><small>{{ sub.name_ar }} · /sub-category/{{ sub.slug }}</small></div><button class="button secondary" @click="editSubcategory(sub)">Edit</button></div><div v-for="child in childrenOf(category.id, sub.id)" :key="child.id" class="tree-child">↳ {{ child.name_en }} <span>{{ child.name_ar }}</span> <button class="button secondary" @click="editSubcategory(child)">Edit</button></div></div>
      </article><p v-if="!categories.length" class="empty">Create your first main category.</p>
    </section>
    <section class="panel"><div class="section-title"><div><p>THREE LEVELS MAXIMUM</p><h2>{{ subForm.id ? 'Edit subcategory' : 'Add a subcategory' }}</h2></div><span>Category → subcategory → nested subcategory</span></div>
      <form class="form-grid" @submit.prevent="saveSubcategory">
        <label>Main category<select v-model.number="subForm.category_id" required><option :value="0" disabled>Choose category</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name_en }}</option></select></label>
        <label>Parent subcategory<select v-model.number="subForm.parent_sub_category_id"><option :value="null">Top-level subcategory</option><option v-for="parent in topLevelSubsForSelectedCategory" :key="parent.id" :value="parent.id">{{ parent.name_en }}</option></select></label>
        <label>English name<input v-model="subForm.name_en" required></label><label>Arabic name<input v-model="subForm.name_ar" dir="rtl" required></label><label>Slug<input v-model="subForm.slug"></label><label>Order<input v-model.number="subForm.order" type="number" min="0"></label>
        <label class="check"><input v-model="subForm.is_active" type="checkbox"> Active</label><label class="check"><input v-model="subForm.show_in_menu" type="checkbox"> Show in navigation</label>
        <label>Desktop banner<input type="file" accept="image/jpeg,image/png,image/webp" @change="pick($event, 'desktop_banner', true)"></label><label>Mobile banner<input type="file" accept="image/jpeg,image/png,image/webp" @change="pick($event, 'mobile_banner', true)"></label>
        <label>English image alt text<input v-model="subForm.banner_alt_en"></label><label>Arabic image alt text<input v-model="subForm.banner_alt_ar" dir="rtl"></label>
        <label class="wide">English description<textarea v-model="subForm.description_en" rows="3"></textarea></label><label class="wide">Arabic description<textarea v-model="subForm.description_ar" rows="3" dir="rtl"></textarea></label>
        <label>English SEO title<input v-model="subForm.meta_title_en"></label><label>Arabic SEO title<input v-model="subForm.meta_title_ar" dir="rtl"></label><label>English SEO description<textarea v-model="subForm.meta_description_en" rows="2"></textarea></label><label>Arabic SEO description<textarea v-model="subForm.meta_description_ar" rows="2" dir="rtl"></textarea></label>
        <div class="actions"><button class="button primary" :disabled="saving || !subForm.category_id">{{ subForm.id ? 'Save subcategory' : 'Create subcategory' }}</button><button class="button secondary" type="button" @click="resetSubcategory">Clear form</button></div>
      </form>
    </section>
  </div></main>
</template>

<script setup lang="ts">
import type { Category, SubCategory } from '~/types/catalog'
definePageMeta({ middleware: ['admin'], adminPermission: 'catalog.manage' })
const { request } = useApi()
const categories = ref<Category[]>([])
const subcategories = ref<SubCategory[]>([])
const loading = ref(false); const saving = ref(false); const notice = ref(''); const error = ref('')
const categoryFiles = ref<Record<string, File>>({}); const subcategoryFiles = ref<Record<string, File>>({})
const emptyCategory = () => ({ id: 0, name_en: '', name_ar: '', slug: '', icon_key: '', order: 0, is_active: true, show_in_menu: true, banner_alt_en: '', banner_alt_ar: '', description_en: '', description_ar: '', meta_title_en: '', meta_title_ar: '', meta_description_en: '', meta_description_ar: '' })
const emptySubcategory = () => ({ id: 0, category_id: 0, parent_sub_category_id: null as number | null, name_en: '', name_ar: '', slug: '', order: 0, is_active: true, show_in_menu: true, banner_alt_en: '', banner_alt_ar: '', description_en: '', description_ar: '', meta_title_en: '', meta_title_ar: '', meta_description_en: '', meta_description_ar: '' })
const categoryForm = reactive(emptyCategory()); const subForm = reactive(emptySubcategory())
const load = async () => { loading.value = true; error.value = ''; try { const [cats, subs] = await Promise.all([request<Category[]>('/category'), request<SubCategory[]>('/sub-category')]); categories.value = [...(cats.data || [])].sort((a,b) => a.order - b.order); subcategories.value = subs.data || [] } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load the category tree.' } finally { loading.value = false } }
const childrenOf = (categoryId: number, parentId: number | null = null) => subcategories.value.filter(item => item.category_id === categoryId && (item.parent_sub_category_id || null) === parentId).sort((a,b) => a.order-b.order)
const topLevelSubsForSelectedCategory = computed(() => childrenOf(subForm.category_id))
const pick = (event: Event, key: string, sub = false) => { const file = (event.target as HTMLInputElement).files?.[0]; if (file) (sub ? subcategoryFiles : categoryFiles).value[key] = file }
const toBody = (source: Record<string, any>, files: Record<string, File>, update = false) => { const body = new FormData(); Object.entries(source).forEach(([key,value]) => { if (key !== 'id' && value !== null && value !== '') body.append(key, typeof value === 'boolean' ? (value ? '1':'0') : String(value)) }); Object.entries(files).forEach(([key,file]) => body.append(key,file)); if (update) body.append('_method','PUT'); return body }
const saveCategory = async () => { saving.value = true; error.value=''; try { const id=categoryForm.id; await request(id ? `/category/${id}` : '/category', { method: 'POST', body: toBody(categoryForm, categoryFiles.value, Boolean(id)) }); notice.value='Category saved.'; resetCategory(); await load() } catch(e) { error.value=e instanceof Error?e.message:'Unable to save category.' } finally { saving.value=false } }
const saveSubcategory = async () => { saving.value=true; error.value=''; try { const id=subForm.id; await request(id ? `/sub-category/${id}` : '/sub-category', { method:'POST', body: toBody(subForm, subcategoryFiles.value, Boolean(id)) }); notice.value='Subcategory saved.'; resetSubcategory(); await load() } catch(e) { error.value=e instanceof Error?e.message:'Unable to save subcategory.' } finally { saving.value=false } }
const editCategory = (item: Category) => { Object.assign(categoryForm, item); categoryForm.id=item.id; categoryFiles.value={} }
const editSubcategory = (item: SubCategory) => { Object.assign(subForm, item); subForm.id=item.id; subcategoryFiles.value={} }
const startSubcategory = (id: number) => { resetSubcategory(); subForm.category_id=id; document.querySelector('.taxonomy-page section:last-of-type')?.scrollIntoView({ behavior:'smooth' }) }
const resetCategory = () => { Object.assign(categoryForm, emptyCategory()); categoryFiles.value={} }
const resetSubcategory = () => { Object.assign(subForm, emptySubcategory()); subcategoryFiles.value={} }
const moveCategory = async (index: number, delta: -1|1) => { const other=categories.value[index+delta]; if (!other) return; saving.value=true; try { await request('/category/reorder',{method:'PUT',body:{category_id:categories.value[index].id,adjacent_category_id:other.id}}); await load() } catch(e) { error.value=e instanceof Error?e.message:'Unable to reorder categories.' } finally { saving.value=false } }
onMounted(load)
</script>

<style scoped>
.taxonomy-page{min-height:100vh;background:#f4f6f8;padding:34px 16px 64px;color:#182631}.taxonomy-shell{max-width:1180px;margin:auto}.taxonomy-page header,.section-title,.tree-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.taxonomy-page header{margin-bottom:22px}.taxonomy-page header p,.section-title p{margin:0;color:#687783;font-size:.7rem;font-weight:800;letter-spacing:.13em}.taxonomy-page h1{margin:5px 0;font-size:2rem}.taxonomy-page header span,.section-title>span{color:#6c7a85}.panel{background:#fff;border:1px solid #e0e6ea;border-radius:14px;padding:22px;margin:16px 0}.section-title{margin-bottom:18px}.section-title h2{margin:4px 0;font-size:1.2rem}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.form-grid label{display:flex;flex-direction:column;gap:6px;color:#42525f;font-size:.8rem;font-weight:650}.form-grid input,.form-grid select,.form-grid textarea{width:100%;min-height:39px;border:1px solid #d5dde3;border-radius:8px;padding:8px 10px;background:white;font:inherit}.form-grid .check{flex-direction:row;align-items:center}.check input{width:auto;min-height:auto;accent-color:#153e57}.wide{grid-column:1/-1}.actions,.row-actions{display:flex;flex-wrap:wrap;gap:7px;align-items:center}.button{border:1px solid #d6dde3;border-radius:8px;padding:8px 12px;background:#fff;color:#253748;font-size:.8rem}.button.primary{background:#153e57;color:#fff;border-color:#153e57;font-weight:700}.button:disabled{opacity:.5}.tree-category{border:1px solid #e1e7eb;border-radius:10px;padding:13px 15px;margin:10px 0}.tree-heading strong{display:block}.tree-heading small,.tree-child span{display:block;color:#71808b;font-size:.77rem}.tree-subcategory{margin:12px 0 0 22px;border-inline-start:2px solid #dbe3e8;padding-inline-start:13px}.tree-child{margin:8px 0 0 24px;color:#405361;font-size:.86rem}.tree-child span{display:inline;margin-inline-start:8px}.tree-child .button{margin-inline-start:8px}.empty{padding:20px;text-align:center;color:#7a8792}.notice,.error{padding:12px 14px;border-radius:8px}.notice{color:#17663b;background:#e8f5ed}.error{color:#a62d21;background:#fff0ee}
@media(max-width:760px){.taxonomy-page header,.section-title,.tree-heading{align-items:flex-start;flex-direction:column}.form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.panel{padding:16px}}
@media(max-width:480px){.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}.taxonomy-page h1{font-size:1.6rem}}
</style>
